  diff --git a/web/server/api/notorganic/openai/[...path].ts b/web/server/api/notorganic/openai/[...path].ts
  new file mode 100644
  index 0000000..56764e9
  --- /dev/null
  +++ b/web/server/api/notorganic/openai/[...path].ts
  @@ -0,0 +1,58 @@
  +import { createError, defineEventHandler, getHeader, getRequestURL } from "h3";
  +import { NOTORGANIC_FEATURE } from "../../../../src/notorganic-provider";
  +import {
  +	createNotOrganicServerClient,
  +	getNotOrganicServerConfig,
  +	NotOrganicOperationalError,
  +} from "../../../../src/notorganic-provider/server";
  +
  +const ALLOWED_ROUTES = new Set([
  +	"v1/chat/completions",
  +	"v1/responses",
  +	"v1/embeddings",
  +	"v1/images/generations",
  +	"v1/audio/speech",
  +	"v1/audio/transcriptions",
  +	"v1/audio/translations",
  +	"v1/models",
  +]);
  +
  +export default defineEventHandler(async (event) => {
  +	const reqUrl = getRequestURL(event);
  +	const route = reqUrl.pathname
  +		.replace(/^\/api\/notorganic\/openai\/?/, "")
  +		.replace(/\/+$/, "");
  +	const allowedMethod =
  +		(event.method === "POST" && ALLOWED_ROUTES.has(route)) ||
  +		(event.method === "GET" && route === "v1/models");
  +	if (!allowedMethod) {
  +		throw createError({ statusCode: 404, statusMessage: "Not found" });
  +	}
  +
  +	try {
  +		const config = getNotOrganicServerConfig();
  +		if (!config.enabled) {
  +			throw createError({ statusCode: 404, statusMessage: "Not found" });
  +		}
  +		const client = await createNotOrganicServerClient(event, NOTORGANIC_FEATURE, config);
  +		return await client.request(`/${route}${reqUrl.search}`, {
  +			method: event.method,
  +			body: event.method === "GET" || event.method === "HEAD" ? undefined : event.req.body,
  +			headers: {
  +				...(getHeader(event, "content-type") ? { "content-type": getHeader(event, "content-type")! } : {}),
  +				...(getHeader(event, "accept") ? { accept: getHeader(event, "accept")! } : {}),
  +			},
  +			idempotencyKey: getHeader(event, "idempotency-key") ?? undefined,
  +			maxCostMicrousd: event.method === "POST" ? config.maxCostMicrousd : undefined,
  +		});
  +	} catch (error) {
  +		if (error instanceof NotOrganicOperationalError) {
  +			throw createError({
  +				statusCode: error.statusCode,
  +				statusMessage: error.message,
  +				data: { code: error.code },
  +			});
  +		}
  +		throw error;
  +	}
  +});

  diff --git a/web/server/api/notorganic/provider/[resource].ts b/web/server/api/notorganic/provider/[resource].ts
  new file mode 100644
  index 0000000..ec2cac0
  --- /dev/null
  +++ b/web/server/api/notorganic/provider/[resource].ts
  @@ -0,0 +1,86 @@
  +import {
  +	createError,
  +	defineEventHandler,
  +	getQuery,
  +	getRouterParam,
  +	readBody,
  +	type H3Event,
  +} from "h3";
  +import {
  +	createNotOrganicServerClient,
  +	getNotOrganicServerConfig,
  +	NotOrganicOperationalError,
  +} from "../../../../src/notorganic-provider/server";
  +import { isNotOrganicPackId } from "../../../../src/notorganic-provider/packs";
  +
  +const RESOURCE_ROUTES = {
  +	account: { method: "GET", path: "/v1/account", feature: "keating:account" },
  +	wallet: { method: "GET", path: "/v1/wallet", feature: "keating:wallet" },
  +	usage: { method: "GET", path: "/v1/usage", feature: "keating:usage" },
  +	checkout: { method: "POST", path: "/v1/billing/checkout", feature: "keating:billing" },
  +} as const;
  +
  +type ResourceName = keyof typeof RESOURCE_ROUTES;
  +
  +function resourceName(event: H3Event): ResourceName | null {
  +	const value = getRouterParam(event, "resource");
  +	return typeof value === "string" && value in RESOURCE_ROUTES
  +		? value as ResourceName
  +		: null;
  +}
  +
  +export default defineEventHandler(async (event) => {
  +	const resource = resourceName(event);
  +	if (!resource) throw createError({ statusCode: 404, statusMessage: "Not found" });
  +	const route = RESOURCE_ROUTES[resource];
  +	if (event.method !== route.method) {
  +		throw createError({ statusCode: 405, statusMessage: "Method not allowed" });
  +	}
  +
  +	try {
  +		const client = await createNotOrganicServerClient(
  +			event,
  +			route.feature,
  +			getNotOrganicServerConfig(),
  +		);
  +		let path = route.path;
  +		let body: string | undefined;
  +		if (resource === "usage") {
  +			const query = getQuery(event);
  +			const parameters = new URLSearchParams();
  +			if (typeof query.after === "string") parameters.set("after", query.after);
  +			if (typeof query.limit === "string") parameters.set("limit", query.limit);
  +			if (parameters.size) path += `?${parameters}`;
  +		} else if (resource === "checkout") {
  +			const input = await readBody<{ product_id?: unknown; return_url?: unknown }>(event);
  +			if (typeof input?.return_url !== "string") {
  +				throw createError({ statusCode: 400, statusMessage: "return_url is required" });
  +			}
  +			if (typeof input?.product_id !== "string" || !isNotOrganicPackId(input.product_id)) {
  +				throw createError({ statusCode: 400, statusMessage: "A valid Keating product_id is required" });
  +			}
  +			const returnUrl = new URL(input.return_url);
  +			if (returnUrl.protocol !== "https:") {
  +				throw createError({ statusCode: 400, statusMessage: "return_url must use HTTPS" });
  +			}
  +			body = JSON.stringify({
  +				product_id: input.product_id,
  +				return_url: returnUrl.toString(),
  +			});
  +		}
  +		return await client.request(path, {
  +			method: route.method,
  +			body,
  +			headers: body ? { "content-type": "application/json" } : undefined,
  +		});
  +	} catch (error) {
  +		if (error instanceof NotOrganicOperationalError) {
  +			throw createError({
  +				statusCode: error.statusCode,
  +				statusMessage: error.message,
  +				data: { code: error.code },
  +			});
  +		}
  +		throw error;
  +	}
  +});

  diff --git a/web/src/notorganic-provider/OPERATIONS.md b/web/src/notorganic-provider/OPERATIONS.md
  new file mode 100644
  index 0000000..2ffc9be
  --- /dev/null
  +++ b/web/src/notorganic-provider/OPERATIONS.md
  @@ -0,0 +1,25 @@
  +# Not Organic hosted provider deployment
  +
  +The browser integration is feature-gated with:
  +
  +- `VITE_NOTORGANIC_ENABLED=true`
  +- `NOTORGANIC_ENABLED=true`
  +
  +The Nitro server additionally requires:
  +
  +- `NOTORGANIC_ISSUER` — HTTPS gateway origin, without `/v1` (normally `https://api.notorganic.info`)
  +- `NOTORGANIC_MAX_COST_MICROUSD` — positive per-request reservation ceiling
  +
  +Enabling those variables is not sufficient to authenticate a user. A Nitro
  +middleware/plugin must put a `NotOrganicSessionAdapter` on each authenticated
  +request at `event.context.notOrganicSessionAdapter`. That adapter must:
  +
  +1. Resolve a durable, server-validated Better Auth session.
  +2. Resolve its linked ATProto DID without accepting a browser-provided DID or
  +   email as proof.
  +3. Sign and exchange the 60-second Keating product assertion.
  +4. Retain the five-minute capability token and DPoP private key server-side.
  +5. Implement refresh, revocation, and session-version checks.
  +
  +Until Keating has that durable auth/storage deployment, hosted calls return
  +`503 notorganic_auth_adapter_unavailable`. This is intentional.

  diff --git a/web/src/notorganic-provider/fetch-adapter.ts b/web/src/notorganic-provider/fetch-adapter.ts
  new file mode 100644
  index 0000000..df29282
  --- /dev/null
  +++ b/web/src/notorganic-provider/fetch-adapter.ts
  @@ -0,0 +1,79 @@
  +export const NOTORGANIC_IDEMPOTENCY_HEADER = "idempotency-key";
  +export const NOTORGANIC_MAX_COST_HEADER = "x-notorganic-max-cost-microusd";
  +
  +export interface NotOrganicDpopInput {
  +	method: string;
  +	url: string;
  +	accessToken: string;
  +}
  +
  +export interface NotOrganicProductSession {
  +	/** Server-validated stable account id. Never populate this from browser input. */
  +	accountId: string;
  +	accessToken: string;
  +	createDpopProof(input: NotOrganicDpopInput): Promise<string>;
  +}
  +
  +export interface NotOrganicFetchAdapterOptions {
  +	baseUrl: string;
  +	session: NotOrganicProductSession;
  +	fetch?: typeof globalThis.fetch;
  +}
  +
  +export interface NotOrganicRequestOptions {
  +	method?: string;
  +	body?: BodyInit | null;
  +	headers?: HeadersInit;
  +	signal?: AbortSignal;
  +	idempotencyKey?: string;
  +	maxCostMicrousd?: number;
  +}
  +
  +function requestId(): string {
  +	return `keating_${crypto.randomUUID()}`;
  +}
  +
  +/**
  + * Small internal adapter matching the hosted SDK's HTTP contract. Keating keeps
  + * this local until @notorganic/sdk is published; callers still send DPoP,
  + * idempotency, and microusd cost headers exactly as the hosted gateway expects.
  + */
  +export class NotOrganicFetchAdapter {
  +	private readonly baseUrl: string;
  +	private readonly fetcher: typeof globalThis.fetch;
  +
  +	constructor(private readonly options: NotOrganicFetchAdapterOptions) {
  +		this.baseUrl = options.baseUrl.replace(/\/+$/, "");
  +		this.fetcher = options.fetch ?? globalThis.fetch;
  +	}
  +
  +	async request(path: string, options: NotOrganicRequestOptions = {}): Promise<Response> {
  +		const method = (options.method ?? "GET").toUpperCase();
  +		const url = `${this.baseUrl}${path.startsWith("/") ? path : `/${path}`}`;
  +		const headers = new Headers(options.headers);
  +		headers.set("authorization", `DPoP ${this.options.session.accessToken}`);
  +		headers.set("dpop", await this.options.session.createDpopProof({
  +			method,
  +			url,
  +			accessToken: this.options.session.accessToken,
  +		}));
  +
  +		if (options.maxCostMicrousd !== undefined) {
  +			if (!Number.isSafeInteger(options.maxCostMicrousd) || options.maxCostMicrousd <= 0) {
  +				throw new TypeError("maxCostMicrousd must be a positive safe integer");
  +			}
  +			headers.set(NOTORGANIC_MAX_COST_HEADER, String(options.maxCostMicrousd));
  +			headers.set(NOTORGANIC_IDEMPOTENCY_HEADER, options.idempotencyKey?.trim() || requestId());
  +		}
  +
  +		return this.fetcher(url, {
  +			method,
  +			headers,
  +			body: options.body,
  +			signal: options.signal,
  +			redirect: "error",
  +			...(options.body ? { duplex: "half" } : {}),
  +		} as RequestInit);
  +	}
  +}
  +

