  +/**
  + * Not Organic credit-pack catalog shown by Keating.
  + *
  + * Dependency-free so both the Vite client (pricing page, purchase dialog) and
  + * the Nitro server (checkout, webhook) share one source of truth. Amounts are
  + * USD; token rates are USD per million tokens and must match the model pricing
  + * configured on the Bifrost gateway so credits draw down at the advertised
  + * rate.
  + */
  +
  +export interface NotOrganicTokenRates {
  +	/** USD per 1M input tokens. */
  +	inputPerMTok: number;
  +	/** USD per 1M output tokens. */
  +	outputPerMTok: number;
  +}
  +
  +export const NOTORGANIC_TOKEN_RATES: NotOrganicTokenRates = {
  +	inputPerMTok: 1,
  +	outputPerMTok: 4,
  +};
  +
  +export type NotOrganicPackId = "keating_pack_10" | "keating_pack_25" | "keating_pack_50";
  +
  +export interface NotOrganicPack {
  +	id: NotOrganicPackId;
  +	label: string;
  +	priceUsd: number;
  +	blurb: string;
  +	popular?: boolean;
  +}
  +
  +export const NOTORGANIC_PACKS: NotOrganicPack[] = [
  +	{
  +		id: "keating_pack_10",
  +		label: "Starter",
  +		priceUsd: 10,
  +		blurb: "Try Keating's hosted model with room to learn a few topics deeply.",
  +	},
  +	{
  +		id: "keating_pack_25",
  +		label: "Plus",
  +		priceUsd: 25,
  +		blurb: "Enough for regular study sessions, quizzes, and animations.",
  +		popular: true,
  +	},
  +	{
  +		id: "keating_pack_50",
  +		label: "Pro",
  +		priceUsd: 50,
  +		blurb: "For daily learners and long-running projects.",
  +	},
  +];
  +
  +export const DEFAULT_NOTORGANIC_PACK_ID: NotOrganicPackId = "keating_pack_10";
  +
  +export function getNotOrganicPack(id: string): NotOrganicPack | undefined {
  +	return NOTORGANIC_PACKS.find((pack) => pack.id === id);
  +}
  +
  +export function isNotOrganicPackId(id: string): id is NotOrganicPackId {
  +	return NOTORGANIC_PACKS.some((pack) => pack.id === id);
  +}
  +
  +/** Millions of input tokens a dollar amount buys at the advertised rate. */
  +export function inputMTokForUsd(usd: number, rates: NotOrganicTokenRates = NOTORGANIC_TOKEN_RATES): number {
  +	return usd / rates.inputPerMTok;
  +}
  +
  +/** Millions of output tokens a dollar amount buys at the advertised rate. */
  +export function outputMTokForUsd(usd: number, rates: NotOrganicTokenRates = NOTORGANIC_TOKEN_RATES): number {
  +	return usd / rates.outputPerMTok;
  +}
  +
  +/** Human-readable token volume for a pack, e.g. "up to 10M in / 2.5M out". */
  +export function formatPackTokenVolume(pack: NotOrganicPack, rates: NotOrganicTokenRates = NOTORGANIC_TOKEN_RATES): string {
  +	const input = formatMTok(inputMTokForUsd(pack.priceUsd, rates));
  +	const output = formatMTok(outputMTokForUsd(pack.priceUsd, rates));
  +	return `up to ${input} input / ${output} output tokens`;
  +}
  +
  +function formatMTok(millions: number): string {
  +	const rounded = Number.isInteger(millions) ? millions.toString() : millions.toFixed(2).replace(/0+$/, "").replace(/\.$/, "");
  +	return `${rounded}M`;
  +}

