  +		throw new NotOrganicOperationalError("Not Organic hosted access is disabled.");
  +	}
  +	return new NotOrganicFetchAdapter({
  +		baseUrl: config.gatewayBaseUrl,
  +		session: await requireNotOrganicProductSession(event, feature),
  +	});
