const IDEMPOTENCY_HEADER = "idempotency-key";
const MAX_COST_HEADER = "x-notorganic-max-cost-microusd";

export class NotOrganicError extends Error {
  constructor(
    message: string,
    public readonly status: number,
    public readonly type: string,
    public readonly code: string | null,
    public readonly param: string | null,
  ) {
    super(message);
  }
}

export function generateIdempotencyKey(): string {
  if (typeof crypto.randomUUID === "function") {
    return `idem_${crypto.randomUUID()}`;
  }
  const bytes = crypto.getRandomValues(new Uint8Array(16));
  bytes[6] = ((bytes[6] ?? 0) & 0x0f) | 0x40;
  bytes[8] = ((bytes[8] ?? 0) & 0x3f) | 0x80;
  const hex = [...bytes].map((byte) => byte.toString(16).padStart(2, "0"));
  return `idem_${hex.slice(0, 4).join("")}-${hex
    .slice(4, 6)
    .join("")}-${hex.slice(6, 8).join("")}-${hex
    .slice(8, 10)
    .join("")}-${hex.slice(10).join("")}`;
}

async function resolveToken(provider: AccessTokenProvider): Promise<string> {
  const token = typeof provider === "function" ? await provider() : provider;
  if (!token) throw new Error("The access token provider returned an empty token.");
  return token;
}

async function throwResponseError(response: Response): Promise<never> {
  let body: OpenAIErrorBody | undefined;
  try {
    body = (await response.json()) as OpenAIErrorBody;
  } catch {
    // Preserve a useful HTTP error when a proxy returns a non-JSON body.
  }
  throw new NotOrganicError(
    body?.error?.message ?? `Gateway request failed with HTTP ${response.status}.`,
    response.status,
    body?.error?.type ?? "http_error",
    body?.error?.code ?? null,
    body?.error?.param ?? null,
  );
}

async function* parseSse<T>(response: Response): AsyncGenerator<T> {
  if (!response.body) return;
  const reader = response.body.pipeThrough(new TextDecoderStream()).getReader();
  let buffer = "";
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buffer += value;
      const events = buffer.split(/\r?\n\r?\n/);
      buffer = events.pop() ?? "";
      for (const event of events) {
        for (const line of event.split(/\r?\n/)) {
          if (!line.startsWith("data:")) continue;
          const data = line.slice(5).trim();
          if (data === "[DONE]") return;
          yield JSON.parse(data) as T;
        }
      }
    }
  } finally {
    reader.releaseLock();
  }
}

