  protected async authenticatedHeaders(
    method: string,
    url: string,
    requestHeaders: Record<string, string> = {},
  ): Promise<{ headers: Headers; accessToken: string }> {
    const accessToken = await resolveToken(this.options.accessToken);
    const dpop = await this.options.dpopProof({
      url,
      method,
      accessToken,
    });
    const headers = new Headers(this.options.headers);
    for (const [name, value] of Object.entries(requestHeaders)) {
      headers.set(name, value);
    }
    headers.set("authorization", `DPoP ${accessToken}`);
    headers.set("dpop", dpop);
    return { headers, accessToken };
  }

  protected async raw(
    method: string,
    path: string,
    body?: BodyInit | Record<string, unknown>,
    options: RequestOptions = {},
  ): Promise<Response> {
    const url = `${this.baseURL}${path}`;
    const { headers } = await this.authenticatedHeaders(
      method,
      url,
      options.headers,
    );
    let encodedBody: BodyInit | undefined;
    if (body instanceof FormData || typeof body === "string") {
      encodedBody = body;
    } else if (body !== undefined) {
      headers.set("content-type", "application/json");
      encodedBody = JSON.stringify(body);
    }
    const response = await this.fetcher(url, {
      method,
      headers,
      body: encodedBody,
      signal: options.signal,
    });
    if (!response.ok) return throwResponseError(response);
    return response;
  }

  protected async json<T>(
    method: string,
    path: string,
    body?: BodyInit | Record<string, unknown>,
    options?: RequestOptions,
  ): Promise<T> {
    return (await this.raw(method, path, body, options)).json() as Promise<T>;
  }

  protected async metered(
    path: string,
    body: BodyInit | Record<string, unknown>,
    options: MeteredRequestOptions = {},
  ): Promise<Response> {
    const maxCost =
      options.maxCostMicrousd ?? this.options.defaultMaxCostMicrousd;
    if (!Number.isSafeInteger(maxCost) || (maxCost ?? 0) <= 0) {
      throw new Error(
        "A positive maxCostMicrousd is required for metered requests.",
      );
    }
    return this.raw("POST", path, body, {
      ...options,
      headers: {
        ...options.headers,
        [IDEMPOTENCY_HEADER]:
          options.idempotencyKey ?? generateIdempotencyKey(),
        [MAX_COST_HEADER]: String(maxCost),
      },
    });
  }

  protected async meteredJson<T>(
    path: string,
    body: BodyInit | Record<string, unknown>,
    options?: MeteredRequestOptions,
  ): Promise<T> {
    return (await this.metered(path, body, options)).json() as Promise<T>;
  }

  private withQuery(
    path: string,
    query: Record<string, string | number | undefined>,
  ): string {
    const parameters = new URLSearchParams();
    for (const [name, value] of Object.entries(query)) {
      if (value !== undefined) parameters.set(name, String(value));
    }
    const suffix = parameters.toString();
    return suffix ? `${path}?${suffix}` : path;
  }
}
